---@class RoleMorphologyParticlesManager
local RoleMorphologyParticlesManager = Class('RoleMorphologyParticlesManager')

-- ========================================================

--- lua:

local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')
local LuaParamType = LuaParametersReader.Type



---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3

local LuaParameters = CS.Engine.Modules.LuaParameters


-- ========================================================


function RoleMorphologyParticlesManager:__init()
    self.controller = nil
end


function RoleMorphologyParticlesManager:__delete()
end




function RoleMorphologyParticlesManager:Start()
    KTool.SetActive(self.controller.gameObject, true)


    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )


    self.particleTFs = LuaParametersReader.Read( self.params, "particleTFs", LuaParametersReader.Type.List ) -- lua array
    --assert( table.count(self.particleTFs) > 0 )

    self:CloseAll()

end




function RoleMorphologyParticlesManager:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function RoleMorphologyParticlesManager:OpenAll()
    for k,e in pairs(self.particleTFs) do
        --e.gameObject:SetActive( true )
        KTool.SetActive( e.gameObject, true )

    end
end 



function RoleMorphologyParticlesManager:CloseAll()
    for k,e in pairs(self.particleTFs) do
        --e.gameObject:SetActive( false )
        KTool.SetActive( e.gameObject, false )
    end
end 




return RoleMorphologyParticlesManager
